CREATE TABLE Metadata(Key TEXT PRIMARY KEY NOT NULL, Value TEXT NOT NULL);
CREATE TABLE Sources(Id TEXT PRIMARY KEY NOT NULL, Title TEXT NOT NULL, Publisher TEXT NOT NULL, Url TEXT NOT NULL, Category TEXT NOT NULL, Summary TEXT NOT NULL, Reference TEXT NOT NULL, CustomSummary TEXT NOT NULL DEFAULT '', AcceptedHash TEXT NOT NULL DEFAULT '', CandidateHash TEXT NOT NULL DEFAULT '', LastAttempt TEXT NOT NULL DEFAULT '', LastSuccess TEXT NOT NULL DEFAULT '', CheckState TEXT NOT NULL DEFAULT 'Noch nicht geprüft');
CREATE TABLE SourceChecks(Id INTEGER PRIMARY KEY AUTOINCREMENT, SourceId TEXT NOT NULL REFERENCES Sources(Id) ON DELETE RESTRICT, CheckedUtc TEXT NOT NULL, State TEXT NOT NULL, Hash TEXT NOT NULL, Detail TEXT NOT NULL);
CREATE TABLE Templates(Id TEXT PRIMARY KEY NOT NULL, Kind TEXT NOT NULL, Title TEXT NOT NULL, SourceId TEXT NOT NULL REFERENCES Sources(Id) ON DELETE RESTRICT, Locator TEXT NOT NULL, Body TEXT NOT NULL, CustomBody TEXT NOT NULL DEFAULT '', Revision INTEGER NOT NULL);
CREATE TABLE Glossary(Id TEXT PRIMARY KEY NOT NULL, Term TEXT NOT NULL, Expanded TEXT NOT NULL, Definition TEXT NOT NULL, CustomDefinition TEXT NOT NULL DEFAULT '', SourceId TEXT NOT NULL REFERENCES Sources(Id) ON DELETE RESTRICT);
CREATE TABLE Records(Id TEXT PRIMARY KEY NOT NULL, Kind TEXT NOT NULL, Code TEXT NOT NULL, Title TEXT NOT NULL, SourceId TEXT NOT NULL REFERENCES Sources(Id) ON DELETE RESTRICT, TemplateId TEXT NULL REFERENCES Templates(Id) ON DELETE RESTRICT, Locator TEXT NOT NULL DEFAULT '', Body TEXT NOT NULL, Owner TEXT NOT NULL DEFAULT '', Status TEXT NOT NULL DEFAULT 'Entwurf', DueDate TEXT NOT NULL DEFAULT '', Scope TEXT NOT NULL DEFAULT '', Version INTEGER NOT NULL DEFAULT 1, IsSeed INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IX_Records_Kind ON Records(Kind);
CREATE TABLE Links(Id TEXT PRIMARY KEY NOT NULL, SourceRecordId TEXT NOT NULL REFERENCES Records(Id) ON DELETE RESTRICT, TargetRecordId TEXT NOT NULL REFERENCES Records(Id) ON DELETE RESTRICT, Type TEXT NOT NULL, Reason TEXT NOT NULL, SourceId TEXT NOT NULL REFERENCES Sources(Id) ON DELETE RESTRICT, UNIQUE(SourceRecordId,TargetRecordId,Type));
CREATE TABLE MappingSuggestions(Id INTEGER PRIMARY KEY AUTOINCREMENT, RequirementId TEXT NOT NULL REFERENCES Templates(Id), ControlId TEXT NOT NULL REFERENCES Templates(Id), Reason TEXT NOT NULL, UNIQUE(RequirementId,ControlId));
CREATE TABLE Evidence(Id TEXT PRIMARY KEY NOT NULL, Title TEXT NOT NULL, ControlId TEXT NOT NULL REFERENCES Records(Id) ON DELETE RESTRICT, SourceId TEXT NOT NULL REFERENCES Sources(Id) ON DELETE RESTRICT, TemplateId TEXT NULL REFERENCES Templates(Id), SourceDescription TEXT NOT NULL, FileName TEXT NOT NULL, Hash TEXT NOT NULL, Content BLOB NOT NULL, CollectedUtc TEXT NOT NULL, ValidUntil TEXT NOT NULL);
CREATE TABLE EvidenceLinks(EvidenceId TEXT NOT NULL REFERENCES Evidence(Id) ON DELETE RESTRICT, ControlId TEXT NOT NULL REFERENCES Records(Id) ON DELETE RESTRICT, PRIMARY KEY(EvidenceId,ControlId));
CREATE TABLE AuditTests(Id TEXT PRIMARY KEY NOT NULL, AuditId TEXT NOT NULL REFERENCES Records(Id) ON DELETE RESTRICT, ControlId TEXT NOT NULL REFERENCES Records(Id) ON DELETE RESTRICT, SourceId TEXT NOT NULL REFERENCES Sources(Id) ON DELETE RESTRICT, EvidenceId TEXT NULL REFERENCES Evidence(Id), Outcome TEXT NOT NULL, Notes TEXT NOT NULL, TestedUtc TEXT NOT NULL, UNIQUE(AuditId,ControlId));
CREATE TABLE Journal(Id INTEGER PRIMARY KEY AUTOINCREMENT, Utc TEXT NOT NULL, Actor TEXT NOT NULL, Action TEXT NOT NULL, EntityId TEXT NOT NULL, Detail TEXT NOT NULL, PreviousHash TEXT NOT NULL, Hash TEXT NOT NULL);
